(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const LEGACY_STORAGE_KEY='ikigaiDemoState_v1';
  const STORAGE_KEY='ikigaiPrototypeState_v2';
  const today = new Date();
  const isoToday = today.toISOString().slice(0,10);
  const money = n => new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);
  const initials = name => name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
  const dateLabel = value => new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short'}).format(new Date(value+'T12:00:00'));
  const escapeHtml = s => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const seed = () => ({
    role:'admin', view:'dashboard',
    members:[],
    coaches:[],
    classes:[],
    bookings:[],
    routines:[],
    ledger:[],
    messages:[],
    absences:[],
    attendance:[],
    nextId:1
  });
  let state;
  try { localStorage.removeItem(LEGACY_STORAGE_KEY); } catch {}
  try { state=JSON.parse(localStorage.getItem(STORAGE_KEY))||seed(); } catch { state=seed(); }
  if (!state.members || !state.classes || !state.ledger) state=seed();
  if (!Array.isArray(state.attendance)) state.attendance=[];
  state.coaches=(state.coaches||[]).map(c=>{const {rate,share,...coach}=c;return {...coach,monthlyFee:coach.monthlyFee??null,monthlyPayments:Array.isArray(coach.monthlyPayments)?coach.monthlyPayments:[]};});
  state.bookings=(state.bookings||[]).map(b=>({...b,status:b.status||'confirmado'}));
  let memberTab='all', memberSearch='', memberStatus='all', accountSearch='', scheduleDate=isoToday, routineFilter='Todas';
  let myMemberId=1;
  const save=()=>localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
  const memberById=id=>state.members.find(m=>m.id===Number(id));
  const classById=id=>state.classes.find(c=>c.id===Number(id));
  const coachByName=name=>state.coaches.find(c=>c.name===name);
  const activeMembers=()=>state.members.filter(m=>m.status==='Activo');
  const bookingsFor=(classId,date=scheduleDate)=>state.bookings.filter(b=>b.classId===Number(classId)&&b.date===date&&b.status==='confirmado');
  const waitlistFor=(classId,date)=>state.bookings.filter(b=>b.classId===Number(classId)&&b.date===date&&b.status==='espera').sort((a,b)=>a.id-b.id);
  const classStartAt=(c,date)=>new Date(`${date}T${c.time}:00`);
  const bookingCutoffPassed=(c,date)=>Date.now()>=classStartAt(c,date).getTime()-40*60*1000;
  const currentPeriod=()=>isoToday.slice(0,7);
  const coachPaidForPeriod=(coach,period=currentPeriod())=>(coach.monthlyPayments||[]).filter(p=>p.period===period).reduce((sum,p)=>sum+Number(p.amount||0),0);
  const coachBalance=(coach,period=currentPeriod())=>coach.monthlyFee==null?null:Number(coach.monthlyFee)-coachPaidForPeriod(coach,period);
  function promoteWaitlist(classId,date){const c=classById(classId);if(!c||bookingsFor(classId,date).length>=c.capacity||bookingCutoffPassed(c,date))return null;const next=waitlistFor(classId,date)[0];if(!next)return null;next.status='confirmado';next.promotedAt=new Date().toISOString();return next;}
  const navLabels={dashboard:'RESUMEN',members:'MIEMBROS',schedule:'TURNOS Y ASISTENCIA',routines:'RUTINAS Y EJERCICIOS',accounts:'CUENTAS CORRIENTES',coaches:'PROFESORES',messages:'AVISOS Y NOTIFICACIONES'};
  function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3400)}
  function setRole(role){state.role=role;save();$('#roleSelect').value=role;const member=memberById(myMemberId);$('#topName').textContent=role==='admin'?'Administración demo':(member?.name||'Miembro sin perfil');$('#topRole').textContent='Simulación · sin autenticación';$('#topAvatar').textContent=role==='admin'?'AD':(member?initials(member.name):'—');$('.admin-only').forEach(el=>el.classList.toggle('hidden',role!=='admin'));if(role==='member'&&['members','accounts','coaches'].includes(state.view))state.view='dashboard';render()}
  function navigate(view){state.view=view;save();$('#sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'smooth'})}
  function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
  function panelHead(title,subtitle='',action=''){return `<div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`}
  function statusPill(status){const cls=status==='Activo'||status==='confirmado'||status==='Recibido'?'ok':status==='Adeuda'||status==='Llegaré tarde'?'warn':status==='Inactivo'||status==='Cancelado'?'bad':'neutral';return `<span class="status ${cls}">${escapeHtml(status)}</span>`}
  function memberAvatar(name){return `<span class="mini-avatar">${escapeHtml(initials(name))}</span>`}
  function stat(label,value,sub,mark,positive=false){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-mark">${mark}</span></div><div class="stat-value">${value}</div><div class="stat-sub ${positive?'positive':''}">${sub}</div></div>`}
  function bookingMembers(bookings){return bookings.map(b=>memberById(b.memberId)?.name).filter(Boolean)}
  function capacityBar(used,max){const pct=Math.min(100,Math.round(used/max*100));return `<div class="capacity"><div class="capacity-label"><span>OCUPACIÓN</span><b>${used}/${max}</b></div><div class="capacity-track"><span class="${used>=max?'full':''}" style="width:${pct}%"></span></div></div>`}
  function renderDashboard(){
    const unread=state.messages.filter(m=>!m.read).length;
    if(state.role==='member'){
      if(!state.members.length){
        return `${heading('VISTA SIMULADA','SIN PERFIL DE MIEMBRO','El prototipo está vacío. El acceso real de miembros se realiza desde el portal conectado.')}${'<div class="empty-state">No hay perfiles ficticios cargados. Esta vista no autentica usuarios ni consulta la API.</div>'}`;
      }
      const m=memberById(myMemberId)||state.members[0]; const upcoming=state.bookings.filter(b=>b.memberId===m.id&&b.date>=isoToday&&['confirmado','espera'].includes(b.status)); const myRoutines=state.routines.filter(r=>r.coach===m.coach||m.plan==='Full mensual').slice(0,2); const pending=state.ledger.filter(x=>x.memberId===m.id).reduce((s,x)=>s+x.amount,0);
      return `${heading('TU ESPACIO IKIGAI','HOLA, '+escapeHtml(m.name.split(' ')[0]).toUpperCase(),'Tu entrenamiento, tus turnos y tu progreso, en un solo lugar.',`<button class="btn primary" data-action="book">＋ Reservar turno</button>`)}<div class="member-hero"><div><p class="eyebrow">TU OBJETIVO · TU CONSTANCIA</p><h2>Forjá tu propósito.</h2><p>Consultá tus rutinas, organizá la semana y avisá si no podés venir.</p></div><div>${statusPill(m.status)}<p class="muted" style="font-size:12px">Plan: ${escapeHtml(m.plan)}</p></div></div><div class="stat-grid">${stat('ASISTENCIAS DEL MES',m.attendance,'Entrenamientos registrados','↗',true)}${stat('TURNOS RESERVADOS',upcoming.filter(b=>b.status==='confirmado').length,'Confirmados · '+upcoming.filter(b=>b.status==='espera').length+' en espera','▦')}${stat('SALDO DE TU CUENTA',money(pending),pending>0?'Saldo pendiente':pending<0?'Tenés saldo a favor':'Cuenta al día','＄')}${stat('RUTINAS DISPONIBLES',state.routines.length,'Planes de entrenamiento','✳')}</div><div class="quick-actions"><button class="quick-action" data-action="book"><span>▦</span><b>Reservar un turno</b><small>Elegí disciplina, profesor y horario. Cupos limitados.</small></button><button class="quick-action" data-action="absence"><span>◷</span><b>Avisar ausencia o demora</b><small>Notificá al gimnasio si no llegás a tiempo.</small></button><button class="quick-action" data-go="routines"><span>✳</span><b>Ver mis rutinas</b><small>Consultá los ejercicios asignados.</small></button></div><div class="two-col"><div class="panel">${panelHead('TUS PRÓXIMOS TURNOS','Reservas confirmadas y lista de espera') }<div class="panel-body">${upcoming.length?upcoming.map(b=>{const c=classById(b.classId);return `<div class="class-row"><div class="class-time">${c?.time||'--:--'}</div><div class="class-info"><b>${escapeHtml(c?.name||'Clase')}</b><small>${dateLabel(b.date)} · ${escapeHtml(c?.coach||'Profesor')} · ${b.status==='espera'?'EN LISTA DE ESPERA':'CONFIRMADO'}</small></div><button class="btn small" data-action="cancel-booking" data-id="${b.id}">Cancelar</button></div>`}).join(''):'<div class="empty-state">Todavía no tenés turnos reservados.</div>'}<div style="margin-top:12px"><button class="text-link" data-go="schedule">Ver todos los turnos →</button></div></div></div><div class="panel">${panelHead('AVISOS DEL GIMNASIO','Novedades recientes')}<div class="panel-body notice-list">${state.messages.slice(0,3).map(messageRow).join('')}<button class="text-link" data-go="messages" style="text-align:left;padding:12px 0 0">Ver todas las notificaciones →</button></div></div></div>`;
    }
    const active=activeMembers().length; const debtors=state.members.filter(m=>m.balance>0&&m.status!=='Inactivo').length; const debtTotal=state.members.reduce((s,m)=>s+Math.max(0,m.balance),0); const attend=state.bookings.filter(b=>b.date===isoToday&&b.status==='confirmado').length;
    const todayClasses=state.classes.filter(c=>c.day===today.getDay()||c.day===1).slice(0,4);
    const classRows=(todayClasses.length?todayClasses:state.classes.slice(0,4)).map(c=>{let used=bookingsFor(c.id,isoToday).length; if(!used)used=Math.min(c.capacity,Math.round(c.capacity*(c.id%5+2)/7));return `<div class="class-row"><div class="class-time">${c.time}</div><div class="class-info"><b>${escapeHtml(c.name)}</b><small>${escapeHtml(c.coach)} · ${c.duration} min</small></div>${capacityBar(used,c.capacity)}</div>`}).join('');
    const latest=state.members.filter(m=>m.balance>0).slice(0,4);
    return `${heading('CENTRO DE CONTROL','RESUMEN GENERAL','Una visión rápida del estado de Ikigai Training.',`<button class="btn" data-go="schedule">▦ Ver turnos</button><button class="btn primary" data-action="add-member">＋ Nuevo miembro</button>`)}<div class="stat-grid">${stat('MIEMBROS ACTIVOS',active,'De '+state.members.length+' perfiles registrados','♙',true)}${stat('ASISTENCIAS DE HOY',attend,'Reservas confirmadas para hoy','▦')}${stat('SALDOS PENDIENTES',money(debtTotal),debtors+' miembros con deuda','＄')}${stat('NOTIFICACIONES',unread+' sin leer','Avisos enviados: '+state.messages.length,'◉')}</div><div class="two-col"><div class="panel">${panelHead('ACTIVIDAD DE HOY','Turnos y capacidad por franja horaria',`<button class="text-link" data-go="schedule">VER AGENDA →</button>`)}<div class="panel-body"><div class="inline-note">Cada franja tiene un límite de <b>7 personas</b>. Las reservas confirmadas ocupan lugar; cancelar libera el cupo.</div><div class="class-list">${classRows}</div></div></div><div class="panel">${panelHead('AVISOS RECIENTES','Comunicaciones del gimnasio',`<button class="text-link" data-go="messages">VER TODOS →</button>`)}<div class="panel-body notice-list">${state.messages.slice(0,3).map(messageRow).join('')}</div></div></div><div class="panel section-gap">${panelHead('SEGUIMIENTO DE CUENTAS','Miembros con saldo pendiente',`<button class="text-link" data-go="accounts">IR A CUENTAS →</button>`)}<div class="table-wrap"><table><thead><tr><th>MIEMBRO</th><th>PLAN</th><th>ESTADO</th><th class="align-right">SALDO</th><th></th></tr></thead><tbody>${latest.map(m=>`<tr><td><div class="person">${memberAvatar(m.name)}<div><b>${escapeHtml(m.name)}</b><small>${escapeHtml(m.email)}</small></div></div></td><td>${escapeHtml(m.plan)}</td><td>${statusPill(m.status)}</td><td class="align-right money due">${money(m.balance)}</td><td><button class="btn small" data-action="ledger" data-id="${m.id}">Ver cuenta</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">No hay saldos pendientes.</td></tr>'}</tbody></table></div></div>`;
  }
  function messageRow(m){return `<div class="notice-row"><div class="notice-icon ${m.kind==='Administración'?'gold':''}">${m.kind==='Rutinas'?'✳':m.kind==='Turnos'?'▦':'◉'}</div><div class="notice-copy"><b>${escapeHtml(m.title)}</b><p>${escapeHtml(m.body)}</p><small>${dateLabel(m.date)} · ${escapeHtml(m.audience)}</small></div></div>`}
  function renderMembers(){const filtered=state.members.filter(m=>{const q=memberSearch.toLowerCase();return (!q||[m.name,m.email,m.phone,m.plan].some(v=>v.toLowerCase().includes(q)))&&(memberStatus==='all'||m.status===memberStatus)&&(memberTab==='all'||(memberTab==='debt'&&m.balance>0)||(memberTab==='active'&&m.status==='Activo')||(memberTab==='inactive'&&m.status==='Inactivo'))});return `${heading('GESTIÓN DE PERSONAS','MIEMBROS','Altas, datos de contacto, planes y estado de cada miembro.',`<button class="btn primary" data-action="add-member">＋ Registrar miembro</button>`)}<div class="stat-grid">${stat('PERFILES REGISTRADOS',state.members.length,'Incluye perfiles inactivos','♙')}${stat('ACTIVOS',activeMembers().length,'Miembros habilitados','✓',true)}${stat('CON SALDO PENDIENTE',state.members.filter(m=>m.balance>0).length,'Revisar cuentas corrientes','＄')}${stat('INACTIVOS',state.members.filter(m=>m.status==='Inactivo').length,'Pueden reactivarse','Ⅱ')}</div><div class="panel"><div class="table-toolbar"><div class="searchbox"><span>⌕</span><input id="memberSearch" placeholder="Buscar por nombre, email, teléfono…" value="${escapeHtml(memberSearch)}"></div><div class="filters"><select id="memberStatusFilter"><option value="all">Todos los estados</option><option ${memberStatus==='Activo'?'selected':''}>Activo</option><option ${memberStatus==='Adeuda'?'selected':''}>Adeuda</option><option ${memberStatus==='Inactivo'?'selected':''}>Inactivo</option></select></div></div><div class="tabs"><button class="tab ${memberTab==='all'?'active':''}" data-member-tab="all">Todos (${state.members.length})</button><button class="tab ${memberTab==='active'?'active':''}" data-member-tab="active">Activos (${activeMembers().length})</button><button class="tab ${memberTab==='debt'?'active':''}" data-member-tab="debt">Con deuda (${state.members.filter(m=>m.balance>0).length})</button><button class="tab ${memberTab==='inactive'?'active':''}" data-member-tab="inactive">Inactivos (${state.members.filter(m=>m.status==='Inactivo').length})</button></div><div class="table-wrap"><table><thead><tr><th>MIEMBRO</th><th>PLAN</th><th>PROFESOR</th><th>ESTADO</th><th class="align-right">SALDO</th><th>ACCIONES</th></tr></thead><tbody>${filtered.map(m=>`<tr><td><div class="person">${memberAvatar(m.name)}<div><b>${escapeHtml(m.name)}</b><small>${escapeHtml(m.email)}</small></div></div></td><td>${escapeHtml(m.plan)}</td><td>${escapeHtml(m.coach)}</td><td>${statusPill(m.status)}</td><td class="align-right money ${m.balance>0?'due':m.balance<0?'credit':''}">${money(m.balance)}</td><td><div class="table-actions"><button class="btn small" data-action="edit-member" data-id="${m.id}">Editar</button><button class="btn small" data-action="ledger" data-id="${m.id}">Cuenta</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">No se encontraron miembros.</td></tr>'}</tbody></table></div><div class="panel-body muted" style="font-size:11px">Mostrando ${filtered.length} perfil(es). Información y operaciones ficticias de la demo.</div></div>`}
  function renderAccounts(){let rows=state.members.filter(m=>m.status!=='Inactivo'&&(!accountSearch||[m.name,m.email].some(x=>x.toLowerCase().includes(accountSearch.toLowerCase()))));let total=state.members.reduce((s,m)=>s+Math.max(0,m.balance),0);let credits=state.members.reduce((s,m)=>s+Math.max(0,-m.balance),0);return `${heading('ADMINISTRACIÓN Y COBRANZAS','CUENTAS CORRIENTES','Saldos, cargos, pagos y movimientos por miembro.',`<button class="btn" data-action="export-ledger">⇩ Exportar CSV</button><button class="btn primary" data-action="add-movement">＋ Cargar movimiento</button>`)}<div class="stat-grid">${stat('SALDOS DEUDORES',money(total),'Importe acumulado pendiente','＄')}${stat('MIEMBROS CON DEUDA',state.members.filter(m=>m.balance>0).length,'Requieren seguimiento','!')}${stat('SALDOS A FAVOR',money(credits),'Crédito de miembros','↙',true)}${stat('MOVIMIENTOS REGISTRADOS',state.ledger.length,'Cargos y pagos de prueba','▤')}</div><div class="panel"><div class="table-toolbar"><div class="searchbox"><span>⌕</span><input id="accountSearch" placeholder="Buscar miembro…" value="${escapeHtml(accountSearch)}"></div><button class="btn small" data-action="add-movement">＋ Registrar pago / cargo</button></div><div class="table-wrap"><table><thead><tr><th>MIEMBRO</th><th>PLAN</th><th>ÚLTIMO MOVIMIENTO</th><th>ESTADO</th><th class="align-right">SALDO ACTUAL</th><th></th></tr></thead><tbody>${rows.map(m=>{let last=state.ledger.filter(x=>x.memberId===m.id).sort((a,b)=>b.date.localeCompare(a.date))[0];return `<tr><td><div class="person">${memberAvatar(m.name)}<div><b>${escapeHtml(m.name)}</b><small>${escapeHtml(m.email)}</small></div></div></td><td>${escapeHtml(m.plan)}</td><td>${last?`${dateLabel(last.date)} · ${escapeHtml(last.description)}`:'—'}</td><td>${statusPill(m.balance>0?'Adeuda':m.balance<0?'A favor':'Al día')}</td><td class="align-right money ${m.balance>0?'due':m.balance<0?'credit':''}">${money(m.balance)}</td><td><button class="btn small" data-action="ledger" data-id="${m.id}">Movimientos</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty-state">No se encontraron cuentas.</td></tr>'}</tbody></table></div></div><div class="inline-note section-gap">Regla de demo: un cargo aumenta el saldo pendiente; un pago lo reduce. En producción los movimientos deberían ser inmutables, auditables y respaldados por comprobantes.</div>`}
  function renderSchedule(){const days=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];const d=new Date(scheduleDate+'T12:00:00');const day=d.getDay();const classes=state.classes.filter(c=>c.day===day).sort((a,b)=>a.time.localeCompare(b.time));const allToday=state.bookings.filter(b=>b.date===scheduleDate&&b.status==='confirmado');return `${heading('ORGANIZACIÓN DE CLASES','TURNOS Y ASISTENCIA','Capacidad configurable por franja; reservas y cancelaciones hasta 40 minutos antes del inicio.',`${state.role==='admin'?'<button class="btn" data-action="add-class">＋ Crear franja</button>':''}<button class="btn primary" data-action="book">＋ Reservar turno</button>`)}<div class="panel"><div class="table-toolbar"><div><p class="eyebrow" style="margin:0 0 3px">FECHA DE TRABAJO</p><div style="font-size:17px;font-weight:700">${days[day]}, ${dateLabel(scheduleDate)}</div></div><div class="filters"><button class="btn small" data-action="prev-date">← Día anterior</button><input aria-label="Fecha de agenda" type="date" id="scheduleDate" value="${scheduleDate}" style="background:#111;color:#eee;border:1px solid #393030;padding:7px;border-radius:3px"><button class="btn small" data-action="next-date">Día siguiente →</button></div></div><div class="panel-body"><div class="stat-grid" style="margin-bottom:15px">${stat('TURNOS DISPONIBLES',classes.length,'Para el día seleccionado','▦')}${stat('RESERVAS CONFIRMADAS',allToday.length,'Personas con lugar asignado','♙')}${stat('CUPOS LIBRES',classes.reduce((s,c)=>s+Math.max(0,c.capacity-bookingsFor(c.id,scheduleDate).length),0),'Entre todas las franjas del día','＋')}${stat('CAPACIDAD TOTAL',classes.reduce((s,c)=>s+c.capacity,0),'Límite configurado por franja','◫')}</div><div class="class-list">${classes.map(c=>{const bs=bookingsFor(c.id,scheduleDate);return `<div class="class-row" style="grid-template-columns:65px minmax(130px,1fr) minmax(110px,180px) auto"><div class="class-time">${c.time}</div><div class="class-info"><b>${escapeHtml(c.name)}</b><small>${escapeHtml(c.coach)} · ${c.duration} min · ${money(c.price)} por lugar (ref.)</small><small>${bs.length?bookingMembers(bs).map(escapeHtml).join(', '):'Sin reservas todavía'}</small></div>${capacityBar(bs.length,c.capacity)}<div class="schedule-actions">${state.role==='member'?`<button class="btn small primary" data-action="book-this" data-id="${c.id}" ${bs.some(b=>b.memberId===myMemberId)?'disabled':''}>${bs.some(b=>b.memberId===myMemberId)?'Reservado':'Reservar'}</button>`:`<button class="btn small" data-action="attendance" data-id="${c.id}">Asistencia</button>`}<button class="btn small" data-action="class-details" data-id="${c.id}">Detalle</button></div></div>`}).join('')||'<div class="empty-state">No hay franjas configuradas para este día. Probá otra fecha o creá una nueva franja.</div>'}</div></div></div><div class="panel section-gap">${panelHead('REGLAS DE RESERVA','Flujo previsto para los miembros')}<div class="panel-body"><div class="two-col" style="margin:0"><div><b>1. Cupo cerrado al llegar a 7</b><p class="muted" style="font-size:12px">Una vez completo, el botón de inscripción deja de estar disponible.</p></div><div><b>2. Ausencias y demoras</b><p class="muted" style="font-size:12px">El miembro avisa desde su app; el administrador ve los avisos para reorganizar los turnos.</p></div></div></div></div>`}
  function renderRoutines(){const list=state.routines.filter(r=>routineFilter==='Todas'||r.type===routineFilter);return `${heading('PLANIFICACIÓN DE ENTRENAMIENTO','RUTINAS Y EJERCICIOS','Catálogo de rutinas organizado por disciplina, nivel y profesor.',`${state.role==='admin'?'<button class="btn primary" data-action="add-routine">＋ Crear rutina</button>':''}`)}<div class="tabs"><button class="tab ${routineFilter==='Todas'?'active':''}" data-routine-filter="Todas">Todas</button>${['Kick Boxing','Tae Kwon Do','Funcional'].map(t=>`<button class="tab ${routineFilter===t?'active':''}" data-routine-filter="${t}">${t}</button>`).join('')}</div><div class="routine-grid">${list.map(r=>`<article class="routine-card"><span class="routine-tag">${escapeHtml(r.type.toUpperCase())} · ${escapeHtml(r.level.toUpperCase())}</span><h3>${escapeHtml(r.title)}</h3><p>${escapeHtml(r.desc)}</p><div class="muted" style="font-size:11px;margin-bottom:8px">Profesor/a: ${escapeHtml(r.coach)}</div>${r.exercises.map(e=>`<div class="exercise-line"><b>${escapeHtml(e[0])}</b><span>${escapeHtml(e[1])}</span></div>`).join('')}<div style="display:flex;gap:6px;margin-top:12px"><button class="btn small" data-action="view-routine" data-id="${r.id}">Ver ficha</button>${state.role==='admin'?`<button class="btn small" data-action="edit-routine" data-id="${r.id}">Editar</button>`:''}</div></article>`).join('')||'<div class="empty-state">No hay rutinas para ese filtro.</div>'}</div><div class="inline-note section-gap">La rutina es una herramienta de planificación. En la versión final, el profesor debería asignar rutinas por alumno y dejar registro de cambios y observaciones.</div>`}
  function renderCoaches(){return `${heading('EQUIPO IKIGAI','PROFESORES','Cada profesor cobra a sus alumnos por su cuenta y registra aquí su obligación mensual fija por uso del espacio.',`${state.role==='admin'?'<button class="btn primary" data-action="add-coach">＋ Agregar profesor</button>':''}`)}<div class="prof-grid">${state.coaches.map(c=>{const members=state.members.filter(m=>m.coach===c.name&&m.status==='Activo');const count=state.bookings.filter(b=>b.date===isoToday&&b.status==='confirmado'&&classById(b.classId)?.coach===c.name).length;const paid=coachPaidForPeriod(c);const balance=coachBalance(c);return `<article class="prof-card"><div class="prof-top"><div class="prof-avatar">${escapeHtml(initials(c.name))}</div><div><h3>${escapeHtml(c.name)}</h3><p>${escapeHtml(c.discipline)}</p>${statusPill(c.active?'Activo':'Inactivo')}</div></div><div class="prof-contact"><span>☎ ${escapeHtml(c.phone)}</span><span>✉ ${escapeHtml(c.email)}</span></div>${state.role==='admin'?`<div class="prof-metrics"><div class="prof-metric"><strong>${members.length}</strong><small>MIEMBROS ACTIVOS ASIGNADOS</small></div><div class="prof-metric"><strong>${count}</strong><small>RESERVAS HOY</small></div><div class="prof-metric"><strong>${c.monthlyFee==null?'Sin configurar':money(c.monthlyFee)}</strong><small>OBLIGACIÓN MENSUAL</small></div><div class="prof-metric"><strong>${balance==null?'—':money(balance)}</strong><small>${balance==null?'CONFIGURAR IMPORTE':balance>0?'SALDO PENDIENTE':balance<0?'SALDO A FAVOR':'MES SALDADO'}</small></div></div><div class="inline-note" style="margin:12px 0 0">Período ${currentPeriod()}: pagos registrados ${money(paid)}. La obligación no depende de reservas ni asistencia.</div><div style="margin-top:12px;display:flex;gap:6px;flex-wrap:wrap"><button class="btn small" data-action="coach-report" data-id="${c.id}">Ver cuenta mensual</button><button class="btn small" data-action="edit-coach" data-id="${c.id}">Editar</button><button class="btn small" data-action="coach-payment" data-id="${c.id}">＋ Registrar pago</button></div>`:''}</article>`}).join('')}</div>${state.role==='member'?'<div class="panel section-gap">'+panelHead('INFORMACIÓN IMPORTANTE','Contactos del equipo')+'<div class="panel-body muted" style="font-size:13px">Los datos publicados son de demostración. En producción, el administrador definirá qué canales de contacto son visibles.</div></div>':''}`}
  function renderMessages(){return `${heading('COMUNICACIÓN INTERNA','AVISOS Y NOTIFICACIONES','Rutinas semanales, novedades del gimnasio y mensajes administrativos.',`${state.role==='admin'?'<button class="btn primary" data-action="send-message">＋ Nuevo aviso</button>':''}`)}${state.role==='admin'?`<div class="stat-grid">${stat('AVISOS PUBLICADOS',state.messages.length,'Historial de comunicaciones','◉')}${stat('SIN LEER',state.messages.filter(m=>!m.read).length,'En este navegador de prueba','●')}${stat('AVISOS DE AUSENCIA',state.absences.length,'Demoras y faltas registradas','◷')}${stat('DESTINATARIOS','Todos','O grupos por condición','♙')}</div>`:''}<div class="two-col"><div><div class="panel">${panelHead('TABLERO DE AVISOS','Comunicaciones del centro') }<div class="panel-body">${state.messages.map(m=>`<article class="message-card"><div class="message-meta"><span>${escapeHtml(m.kind.toUpperCase())} · ${dateLabel(m.date)}</span><span>${escapeHtml(m.audience)}</span></div><h3 style="margin-top:8px">${escapeHtml(m.title)}</h3><p>${escapeHtml(m.body)}</p><div class="message-meta"><span>${m.read?'LEÍDO':'PENDIENTE DE LECTURA'}</span>${state.role==='member'?`<button class="text-link" data-action="read-message" data-id="${m.id}">${m.read?'Leído':'Marcar leído'}</button>`:`<button class="text-link" data-action="delete-message" data-id="${m.id}">Eliminar</button>`}</div></article>`).join('')||'<div class="empty-state">Todavía no hay avisos.</div>'}</div></div></div><div class="panel">${panelHead(state.role==='admin'?'AVISOS DE LOS MIEMBROS':'CONTACTO DEL GIMNASIO',state.role==='admin'?'Ausencias y llegadas tarde':'Canales de comunicación')}<div class="panel-body">${state.role==='admin'?(state.absences.map(a=>{const m=memberById(a.memberId);return `<div class="notice-row"><div class="notice-icon gold">◷</div><div class="notice-copy"><b>${escapeHtml(m?.name||'Miembro')}</b><p>${escapeHtml(a.type)} · ${escapeHtml(a.note||'Sin detalle')}</p><small>${dateLabel(a.date)} · ${statusPill(a.status)}</small></div></div>`}).join('')||'<div class="empty-state">No hay avisos de ausencia.</div>'):`<div class="notice-row"><div class="notice-icon">☎</div><div class="notice-copy"><b>Agustín Navarro · Dirección</b><p>11 6282-1564</p><small>Contacto general del gimnasio</small></div></div><div class="notice-row"><div class="notice-icon">◎</div><div class="notice-copy"><b>Instagram</b><p>@ikigai_training</p><small>Canal público del centro</small></div></div>`}</div></div></div>`}
  function render(){if(!navLabels[state.view])state.view='dashboard';$('#breadcrumbLabel').textContent=navLabels[state.view];$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#page').innerHTML=({dashboard:renderDashboard,members:renderMembers,accounts:renderAccounts,schedule:renderSchedule,routines:renderRoutines,coaches:renderCoaches,messages:renderMessages}[state.view])();$('#memberNavCount').textContent=state.members.length;$('#topName').textContent=state.role==='admin'?'Agustín Navarro':(memberById(myMemberId)?.name||'Lucía Fernández');$('#topRole').textContent=state.role==='admin'?'Administrador':'Miembro';$('#topAvatar').textContent=state.role==='admin'?'AN':initials(memberById(myMemberId)?.name||'Lucía Fernández');}
  function modal(title,body,submitLabel='Guardar',onSubmit=null,secondary=null){const dlg=$('#modal');$('#modalContent').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close-modal" type="button" data-action="close-modal">×</button></div><form id="modalForm"><div class="modal-body">${body}</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cerrar</button>${secondary?`<button type="button" class="btn" id="modalSecondary">＋ ${secondary.label}</button>`:`<button type="submit" class="btn primary">${submitLabel}</button>`}</div></form>`;dlg.showModal();const form=$('#modalForm');form.addEventListener('submit',e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(form));});if(secondary)$('#modalSecondary').addEventListener('click',secondary.action);}
  function ledgerModal(id){const m=memberById(id);if(!m)return;const lines=state.ledger.filter(x=>x.memberId===m.id).sort((a,b)=>b.date.localeCompare(a.date));const charges=lines.filter(x=>x.amount>0).reduce((s,x)=>s+x.amount,0);const payments=-lines.filter(x=>x.amount<0).reduce((s,x)=>s+x.amount,0);modal('CUENTA CORRIENTE · '+escapeHtml(m.name),`<div class="balance-summary"><div class="balance-box"><small>SALDO ACTUAL</small><strong style="color:${m.balance>0?'#ff8b91':m.balance<0?'#70d89b':'#eee'}">${money(m.balance)}</strong></div><div class="balance-box"><small>CARGOS</small><strong>${money(charges)}</strong></div><div class="balance-box"><small>PAGOS</small><strong>${money(payments)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>MOVIMIENTO</th><th>CONCEPTO</th><th class="align-right">IMPORTE</th></tr></thead><tbody>${lines.map(x=>`<tr><td>${dateLabel(x.date)}</td><td>${escapeHtml(x.type)}</td><td>${escapeHtml(x.description)}</td><td class="align-right money ${x.amount>0?'due':'credit'}">${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">Sin movimientos.</td></tr>'}</tbody></table></div><p class="field-help" style="margin-top:12px">Vista de demostración. No reemplaza una cuenta contable ni un recibo válido.</p>`, 'Registrar movimiento',null,{label:'Registrar movimiento',action:()=>{closeModal();movementModal(m.id)}});}
  function movementModal(preselected=null){const options=state.members.map(m=>`<option value="${m.id}" ${Number(preselected)===m.id?'selected':''}>${escapeHtml(m.name)}</option>`).join('');modal('REGISTRAR MOVIMIENTO',`<div class="form-grid"><div class="field full"><label>MIEMBRO *</label><select name="memberId" required>${options}</select></div><div class="field"><label>TIPO *</label><select name="type"><option value="Pago">Pago (reduce deuda)</option><option value="Cargo">Cargo (aumenta deuda)</option></select></div><div class="field"><label>IMPORTE EN PESOS *</label><input type="number" name="amount" min="1" step="1" required placeholder="Ej. 25000"></div><div class="field"><label>FECHA *</label><input type="date" name="date" value="${isoToday}" required></div><div class="field"><label>MEDIO (REFERENCIA)</label><select name="method"><option>Efectivo</option><option>Transferencia</option><option>Mercado Pago</option><option>Otro</option></select></div><div class="field full"><label>CONCEPTO *</label><input name="description" required placeholder="Cuota mensual, pago parcial…"></div></div>`,`Guardar movimiento`,fd=>{const m=memberById(fd.get('memberId'));const amount=Math.abs(Number(fd.get('amount')));if(!m||!amount||!fd.get('description').trim()){toast('Revisá los datos del movimiento.',true);return;}const type=fd.get('type');const signed=type==='Pago'?-amount:amount;m.balance+=signed;if(m.balance<=0&&m.status==='Adeuda')m.status='Activo';if(m.balance>0&&m.status==='Activo')m.status='Adeuda';state.ledger.push({id:state.nextId++,memberId:m.id,date:fd.get('date'),type,description:fd.get('description')+' · '+fd.get('method'),amount:signed});save();closeModal();render();toast('Movimiento registrado en la demo.');});}
  function closeModal(){$('#modal').close()}
  function addMemberModal(existing=null){const m=existing?memberById(existing):null;const coaches=state.coaches.map(c=>`<option ${m?.coach===c.name?'selected':''}>${escapeHtml(c.name)}</option>`).join('');modal(m?'EDITAR MIEMBRO':'REGISTRAR MIEMBRO',`<div class="form-grid"><div class="field full"><label>NOMBRE Y APELLIDO *</label><input name="name" required value="${escapeHtml(m?.name||'')}" placeholder="Nombre Apellido"></div><div class="field"><label>EMAIL *</label><input name="email" type="email" required value="${escapeHtml(m?.email||'')}" placeholder="nombre@email.com"></div><div class="field"><label>TELÉFONO</label><input name="phone" value="${escapeHtml(m?.phone||'')}" placeholder="11 5555-0000"></div><div class="field"><label>PLAN</label><select name="plan">${['Full mensual','Kick Boxing','Tae Kwon Do','Funcional'].map(x=>`<option ${m?.plan===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>ESTADO</label><select name="status">${['Activo','Adeuda','Inactivo'].map(x=>`<option ${m?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>PROFESOR DE REFERENCIA</label><select name="coach">${coaches}</select></div>${m?'':`<div class="field"><label>SALDO INICIAL</label><input type="number" name="balance" min="0" value="0"></div><div class="field"><label>FECHA DE ALTA</label><input type="date" name="join" value="${isoToday}"></div>`}</div>`,m?'Guardar cambios':'Crear miembro',fd=>{const name=fd.get('name').trim(),email=fd.get('email').trim();if(!name||!email){toast('El nombre y el email son obligatorios.',true);return;}if(state.members.some(x=>x.email.toLowerCase()===email.toLowerCase()&&x.id!==m?.id)){toast('Ya existe un miembro con ese email.',true);return;}const fields={name,email,phone:fd.get('phone').trim(),plan:fd.get('plan'),status:fd.get('status'),coach:fd.get('coach')};if(m){Object.assign(m,fields);toast('Perfil actualizado.')}else{const member={id:state.nextId++,...fields,balance:Number(fd.get('balance')||0),paid:0,join:fd.get('join')||isoToday,attendance:0};state.members.push(member);if(member.balance>0)state.ledger.push({id:state.nextId++,memberId:member.id,date:member.join,type:'Cargo',description:'Saldo inicial',amount:member.balance});toast('Miembro creado.')}save();closeModal();render();});}
  function bookModal(preClassId=null){const options=state.classes.map(c=>{const count=bookingsFor(c.id,scheduleDate).length,waiting=waitlistFor(c.id,scheduleDate).length;return `<option value="${c.id}" ${Number(preClassId)===c.id?'selected':''}>${c.time} · ${escapeHtml(c.name)} · ${escapeHtml(c.coach)} (${count}/${c.capacity})${count>=c.capacity?' · LISTA DE ESPERA ('+waiting+')':''}</option>`}).join('');modal('RESERVAR TURNO',`<div class="inline-note">La capacidad depende de cada franja. Las reservas y cancelaciones se cierran 40 minutos antes del inicio. Si una franja está completa, podés anotarte en la lista de espera.</div><div class="form-grid"><div class="field full"><label>MIEMBRO</label><select name="memberId">${state.role==='member'?`<option value="${myMemberId}">${escapeHtml(memberById(myMemberId)?.name||'Miembro')}</option>`:state.members.filter(m=>m.status==='Activo').map(m=>`<option value="${m.id}">${escapeHtml(m.name)}</option>`).join('')}</select></div><div class="field full"><label>FRANJA *</label><select name="classId" required>${options}</select></div><div class="field full"><label>FECHA *</label><input type="date" name="date" value="${state.role==='member'?isoToday:scheduleDate}" required></div></div>`,`Confirmar reserva`,fd=>{const memberId=Number(fd.get('memberId')),classId=Number(fd.get('classId')),date=fd.get('date'),c=classById(classId);if(!c||!memberById(memberId)){toast('Seleccioná un miembro y una franja.',true);return;}if(memberById(memberId).status!=='Activo'){toast('Sólo se pueden reservar turnos para miembros activos.',true);return;}if(date<isoToday){toast('No se puede reservar una fecha pasada.',true);return;}if(new Date(date+'T12:00:00').getDay()!==c.day){toast('Esta franja no funciona el día seleccionado. Elegí una fecha compatible con su día semanal.',true);return;}if(bookingCutoffPassed(c,date)){toast('Las reservas se cierran 40 minutos antes del inicio.',true);return;}const existing=state.bookings.find(b=>b.memberId===memberId&&b.classId===classId&&b.date===date&&['confirmado','espera'].includes(b.status));if(existing){toast('Este miembro ya tiene una reserva o está en espera para esa franja.',true);return;}const full=bookingsFor(classId,date).length>=c.capacity;const status=full?'espera':'confirmado';state.bookings.push({id:state.nextId++,memberId,classId,date,status,createdAt:new Date().toISOString()});save();closeModal();scheduleDate=date;render();toast(full?'Franja completa: quedaste en la lista de espera.':'Reserva confirmada en la demo.');});}
  function absenceModal(){const options=state.role==='member'?`<option value="${myMemberId}">${escapeHtml(memberById(myMemberId)?.name||'Miembro')}</option>`:state.members.filter(m=>m.status==='Activo').map(m=>`<option value="${m.id}">${escapeHtml(m.name)}</option>`).join('');modal('AVISAR AUSENCIA O DEMORA',`<div class="form-grid"><div class="field full"><label>MIEMBRO</label><select name="memberId">${options}</select></div><div class="field"><label>TIPO DE AVISO</label><select name="type"><option>Faltaré</option><option>Llegaré tarde</option></select></div><div class="field"><label>FECHA</label><input type="date" name="date" value="${isoToday}" required></div><div class="field full"><label>DETALLE (OPCIONAL)</label><textarea name="note" placeholder="Ej. Llegaré unos 10 minutos tarde."></textarea></div></div><p class="field-help">Este aviso quedará visible en el panel del administrador en esta demo local.</p>`,`Enviar aviso`,fd=>{state.absences.unshift({id:state.nextId++,memberId:Number(fd.get('memberId')),date:fd.get('date'),type:fd.get('type'),note:fd.get('note').trim(),status:'Recibido'});save();closeModal();render();toast('Aviso registrado. Agustín podrá verlo en Notificaciones.');});}
  function messageModal(){modal('PUBLICAR AVISO',`<div class="notice-form"><div class="field"><label>TÍTULO *</label><input name="title" required placeholder="Ej. Rutinas de la semana"></div><div class="field"><label>MENSAJE *</label><textarea name="body" required placeholder="Escribí el aviso que verán los miembros…"></textarea></div><div class="form-grid"><div class="field"><label>DESTINATARIOS</label><select name="audience"><option>Todos los miembros</option><option>Miembros con saldo pendiente</option><option>Miembros activos</option></select></div><div class="field"><label>CATEGORÍA</label><select name="kind"><option>General</option><option>Rutinas</option><option>Administración</option><option>Turnos</option></select></div></div></div>`,`Publicar aviso`,fd=>{state.messages.unshift({id:state.nextId++,title:fd.get('title').trim(),body:fd.get('body').trim(),audience:fd.get('audience'),date:isoToday,kind:fd.get('kind'),read:false});save();closeModal();render();toast('Aviso publicado en el panel de la demo.');});}
  function routineModal(existing=null){const r=existing?state.routines.find(x=>x.id===existing):null;modal(r?'EDITAR RUTINA':'CREAR RUTINA',`<div class="form-grid"><div class="field full"><label>NOMBRE *</label><input name="title" required value="${escapeHtml(r?.title||'')}" placeholder="Ej. Fuerza base B"></div><div class="field"><label>DISCIPLINA</label><select name="type">${['Kick Boxing','Tae Kwon Do','Funcional'].map(x=>`<option ${r?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>NIVEL</label><select name="level">${['Inicial','Intermedio','Avanzado','Todos los niveles'].map(x=>`<option ${r?.level===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>PROFESOR</label><select name="coach">${state.coaches.map(c=>`<option ${r?.coach===c.name?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field full"><label>DESCRIPCIÓN</label><textarea name="desc">${escapeHtml(r?.desc||'')}</textarea></div><div class="field full"><label>EJERCICIOS (UNO POR LÍNEA: NOMBRE | SERIES/REPETICIONES)</label><textarea name="exercises" placeholder="Sentadillas | 3 × 12\nPlancha | 3 × 30 s">${escapeHtml(r?r.exercises.map(e=>e.join(' | ')).join('\n'):'')}</textarea></div></div>`,r?'Guardar rutina':'Crear rutina',fd=>{const title=fd.get('title').trim();if(!title){toast('La rutina necesita un nombre.',true);return;}const exercises=fd.get('exercises').split('\n').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x[0]).map(x=>[x[0],x[1]||'Según indicación']);const obj={id:r?.id||state.nextId++,title,type:fd.get('type'),level:fd.get('level'),coach:fd.get('coach'),desc:fd.get('desc').trim(),exercises};if(r)Object.assign(r,obj);else state.routines.push(obj);save();closeModal();render();toast('Rutina guardada.');});}
  function coachModal(id=null){const c=id?state.coaches.find(x=>x.id===Number(id)):null;modal(c?'EDITAR PROFESOR':'AGREGAR PROFESOR',`<div class="form-grid"><div class="field full"><label>NOMBRE Y APELLIDO *</label><input name="name" required value="${escapeHtml(c?.name||'')}"></div><div class="field full"><label>DISCIPLINA / FUNCIÓN</label><input name="discipline" value="${escapeHtml(c?.discipline||'')}"></div><div class="field"><label>TELÉFONO</label><input name="phone" value="${escapeHtml(c?.phone||'')}"></div><div class="field"><label>EMAIL</label><input name="email" type="email" value="${escapeHtml(c?.email||'')}"></div><div class="field full"><label>OBLIGACIÓN MENSUAL POR USO DEL ESPACIO ($)</label><input name="monthlyFee" type="number" min="0" step="0.01" value="${c?.monthlyFee??''}" placeholder="Dejar vacío hasta acordar el importe"></div><div class="field full"><label>ESTADO</label><select name="active"><option value="true" ${c?.active!==false?'selected':''}>Activo</option><option value="false" ${c?.active===false?'selected':''}>Inactivo</option></select></div></div><p class="field-help">El profesor cobra directamente a sus alumnos. Este importe representa exclusivamente su obligación mensual con el gimnasio y no depende de las reservas ni de la asistencia.</p>`,c?'Guardar cambios':'Agregar profesor',fd=>{const name=fd.get('name').trim();if(!name){toast('El nombre es obligatorio.',true);return;}const raw=fd.get('monthlyFee');const monthlyFee=raw===''?null:Number(raw);if(monthlyFee!==null&&(!Number.isFinite(monthlyFee)||monthlyFee<0)){toast('La obligación mensual debe ser un importe válido no negativo.',true);return;}const obj={id:c?.id||state.nextId++,name,discipline:fd.get('discipline').trim(),phone:fd.get('phone').trim(),email:fd.get('email').trim(),monthlyFee,monthlyPayments:c?.monthlyPayments||[],active:fd.get('active')==='true'};if(c)Object.assign(c,obj);else state.coaches.push(obj);save();closeModal();render();toast('Datos de profesor guardados.');});}
  function classModal(){modal('CREAR FRANJA HORARIA',`<div class="form-grid"><div class="field"><label>DISCIPLINA *</label><select name="name">${['Kick Boxing','Tae Kwon Do','Funcional','Entrenamiento abierto'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>PROFESOR</label><select name="coach">${state.coaches.filter(c=>c.active).map(c=>`<option>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field"><label>DÍA *</label><select name="day">${[['Domingo',0],['Lunes',1],['Martes',2],['Miércoles',3],['Jueves',4],['Viernes',5],['Sábado',6]].map(([n,v])=>`<option value="${v}" ${v===new Date(scheduleDate+'T12:00:00').getDay()?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>HORA *</label><input type="time" name="time" value="18:00" required></div><div class="field"><label>DURACIÓN EN MINUTOS</label><input type="number" name="duration" min="20" max="180" value="60" required></div><div class="field"><label>CUPO MÁXIMO</label><input type="number" name="capacity" min="1" max="30" value="7" required></div><div class="field full"><label>VALOR DE CLASE (REFERENCIA)</label><input type="number" name="price" min="0" value="8000"></div></div>`,`Crear franja`,fd=>{const capacity=Number(fd.get('capacity'));if(!Number.isInteger(capacity)||capacity<1||capacity>30){toast('El cupo debe ser un número entero entre 1 y 30.',true);return;}const c={id:state.nextId++,name:fd.get('name'),coach:fd.get('coach'),day:Number(fd.get('day')),time:fd.get('time'),duration:Number(fd.get('duration')),capacity,price:Number(fd.get('price'))};state.classes.push(c);save();closeModal();render();toast('Franja horaria creada.');});}
  function attendanceModal(classId){const c=classById(classId);if(!c)return;const bs=bookingsFor(c.id,scheduleDate);const records=state.attendance.filter(a=>a.classId===c.id&&a.date===scheduleDate);modal('ASISTENCIA · '+escapeHtml(c.name),`<p class="field-help" style="margin-bottom:12px">${dateLabel(scheduleDate)} · ${c.time} · ${escapeHtml(c.coach)}</p><div style="display:grid;gap:12px">${bs.map(b=>{const prior=records.find(a=>a.bookingId===b.id);return `<label class="checkbox-line"><input type="checkbox" name="present-${b.id}" ${prior?prior.present?'checked':'':'checked'}> ${escapeHtml(memberById(b.memberId)?.name||'Miembro')} <span class="muted">(${prior?(prior.present?'Presente':'Ausente'):'sin registrar'})</span></label>`}).join('')||'<div class="empty-state">No hay reservas confirmadas para esta franja.</div>'}</div><p class="field-help" style="margin-top:12px">El registro se guarda por fecha y reserva; podés corregirlo sin duplicar la asistencia.</p>`,`Guardar asistencia`,fd=>{const now=new Date().toISOString();let presentCount=0;bs.forEach(b=>{const present=fd.has('present-'+b.id);let record=state.attendance.find(a=>a.bookingId===b.id&&a.date===scheduleDate);const wasPresent=record?.present===true;if(!record){record={id:state.nextId++,classId:c.id,date:scheduleDate,bookingId:b.id,memberId:b.memberId,present,recordedAt:now,updatedAt:now};state.attendance.push(record);}else{record.present=present;record.updatedAt=now;}if(wasPresent!==present){const member=memberById(b.memberId);if(member)member.attendance=Math.max(0,Number(member.attendance||0)+(present?1:-1));}if(present)presentCount++;});save();closeModal();render();toast('Asistencia guardada: '+presentCount+' presentes de '+bs.length+' reservas.');});}
  function classDetails(id){const c=classById(id);if(!c)return;const bs=bookingsFor(c.id,scheduleDate),waiting=waitlistFor(c.id,scheduleDate);modal('DETALLE DE FRANJA',`<div class="balance-summary"><div class="balance-box"><small>HORA</small><strong>${c.time}</strong></div><div class="balance-box"><small>CUPO</small><strong>${bs.length}/${c.capacity}</strong></div><div class="balance-box"><small>EN ESPERA</small><strong>${waiting.length}</strong></div></div><p><b>${escapeHtml(c.name)}</b></p><p class="muted">Profesor/a: ${escapeHtml(c.coach)} · Duración ${c.duration} minutos</p><hr style="border:0;border-top:1px solid #302525;margin:15px 0"><b>Reservas de esta fecha</b><div style="display:grid;gap:8px;margin-top:10px">${bs.map(b=>`<div class="notice-row">${memberAvatar(memberById(b.memberId)?.name||'?')}<div class="notice-copy"><b>${escapeHtml(memberById(b.memberId)?.name||'Miembro')}</b><small>${escapeHtml(b.status)}</small></div>${state.role==='admin'?`<button type="button" class="btn small" data-action="admin-cancel-booking" data-id="${b.id}">Quitar</button>`:''}</div>`).join('')||'<p class="muted">Sin reservas confirmadas.</p>'}</div><hr style="border:0;border-top:1px solid #302525;margin:15px 0"><b>Lista de espera</b><div style="display:grid;gap:8px;margin-top:10px">${waiting.map((b,index)=>`<div class="notice-row">${memberAvatar(memberById(b.memberId)?.name||'?')}<div class="notice-copy"><b>${index+1}. ${escapeHtml(memberById(b.memberId)?.name||'Miembro')}</b><small>En espera</small></div>${state.role==='admin'?`<button type="button" class="btn small" data-action="admin-cancel-booking" data-id="${b.id}">Quitar</button>`:''}</div>`).join('')||'<p class="muted">No hay personas en espera.</p>'}</div>`, 'Cerrar',()=>closeModal());}
  function coachReport(id){const c=state.coaches.find(x=>x.id===Number(id));if(!c)return;const period=currentPeriod(),paid=coachPaidForPeriod(c,period),balance=coachBalance(c,period);const payments=(c.monthlyPayments||[]).filter(p=>p.period===period).sort((a,b)=>b.date.localeCompare(a.date));modal('CUENTA MENSUAL · '+escapeHtml(c.name),`<div class="balance-summary"><div class="balance-box"><small>PERÍODO</small><strong>${period}</strong></div><div class="balance-box"><small>OBLIGACIÓN</small><strong>${c.monthlyFee==null?'Sin configurar':money(c.monthlyFee)}</strong></div><div class="balance-box"><small>PAGADO</small><strong>${money(paid)}</strong></div></div><div class="inline-note">${balance==null?'Configurá la obligación mensual acordada para poder calcular el saldo.':balance>0?'Saldo pendiente: <b>'+money(balance)+'</b>.':balance<0?'Saldo a favor: <b>'+money(-balance)+'</b>.':'La obligación de este período está saldada.'} Los pagos se registran por período y no se calculan a partir de reservas o asistencia.</div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>MEDIO</th><th>CONCEPTO</th><th>IMPORTE</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${dateLabel(p.date)}</td><td>${escapeHtml(p.method||'—')}</td><td>${escapeHtml(p.note||'Pago mensual')}</td><td>${money(p.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">Sin pagos registrados para este período.</td></tr>'}</tbody></table></div><div style="margin-top:14px"><button type="button" class="btn primary" data-action="coach-payment" data-id="${c.id}">＋ Registrar pago</button></div>`,`Cerrar`,()=>closeModal());}
  function coachPaymentModal(id){const c=state.coaches.find(x=>x.id===Number(id));if(!c)return;modal('REGISTRAR PAGO MENSUAL · '+escapeHtml(c.name),`<div class="inline-note">Este registro corresponde al pago del profesor al gimnasio por uso del espacio. No representa cobros del profesor a sus alumnos.</div><div class="form-grid"><div class="field"><label>PERÍODO *</label><input type="month" name="period" value="${currentPeriod()}" required></div><div class="field"><label>FECHA DE PAGO *</label><input type="date" name="date" value="${isoToday}" required></div><div class="field full"><label>IMPORTE RECIBIDO ($) *</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div class="field full"><label>MEDIO DE PAGO</label><select name="method"><option>Transferencia</option><option>Efectivo</option><option>Otro</option></select></div><div class="field full"><label>NOTA / REFERENCIA</label><input name="note" maxlength="160" placeholder="Ej. Pago parcial del mes"></div></div>`, 'Guardar pago', fd=>{const period=fd.get('period'),date=fd.get('date'),amount=Number(fd.get('amount'));if(!/^\d{4}-\d{2}$/.test(period)||!date||!Number.isFinite(amount)||amount<=0){toast('Revisá el período, la fecha y el importe del pago.',true);return;}if(!Array.isArray(c.monthlyPayments))c.monthlyPayments=[];c.monthlyPayments.push({id:state.nextId++,period,date,amount,method:fd.get('method'),note:fd.get('note').trim(),createdAt:new Date().toISOString()});save();closeModal();render();toast('Pago mensual registrado.');});}
  function viewRoutine(id){const r=state.routines.find(x=>x.id===Number(id));if(!r)return;modal('FICHA DE RUTINA',`<span class="routine-tag">${escapeHtml(r.type)} · ${escapeHtml(r.level)}</span><h3>${escapeHtml(r.title)}</h3><p class="muted">${escapeHtml(r.desc)}</p><p class="muted">Profesor/a: ${escapeHtml(r.coach)}</p><div style="margin-top:12px">${r.exercises.map((e,i)=>`<div class="class-row"><div class="class-time">${String(i+1).padStart(2,'0')}</div><div class="class-info"><b>${escapeHtml(e[0])}</b><small>Series / repetición / duración</small></div><strong>${escapeHtml(e[1])}</strong></div>`).join('')}</div><p class="field-help" style="margin-top:12px">Ajustar carga y ejecución con el profesor responsable.</p>`,`Cerrar`,()=>closeModal());}
  function exportCSV(){const rows=[['Miembro','Email','Fecha','Tipo','Concepto','Importe','Saldo actual']];state.ledger.forEach(x=>{const m=memberById(x.memberId);rows.push([m?.name||'',m?.email||'',x.date,x.type,x.description,x.amount,m?.balance||0])});const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));a.download='ikigai-cuentas-demo.csv';a.click();URL.revokeObjectURL(a.href);toast('CSV de muestra generado.');}
  function exportMembers(){const rows=[['Nombre','Email','Teléfono','Plan','Estado','Saldo','Profesor']];state.members.forEach(m=>rows.push([m.name,m.email,m.phone,m.plan,m.status,m.balance,m.coach]));const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));a.download='ikigai-miembros-demo.csv';a.click();URL.revokeObjectURL(a.href);toast('CSV de miembros generado.');}
  function runAction(action,id){switch(action){case'add-member':addMemberModal();break;case'edit-member':addMemberModal(Number(id));break;case'ledger':ledgerModal(Number(id));break;case'add-movement':movementModal();break;case'export-ledger':exportCSV();break;case'export-members':exportMembers();break;case'book':bookModal();break;case'book-this':bookModal(Number(id));break;case'absence':absenceModal();break;case'add-routine':routineModal();break;case'edit-routine':routineModal(Number(id));break;case'view-routine':viewRoutine(Number(id));break;case'add-coach':coachModal();break;case'edit-coach':coachModal(Number(id));break;case'coach-report':coachReport(Number(id));break;case'coach-payment':coachPaymentModal(Number(id));break;case'add-class':classModal();break;case'attendance':attendanceModal(Number(id));break;case'class-details':classDetails(Number(id));break;case'send-message':messageModal();break;case'read-message':{const m=state.messages.find(x=>x.id===Number(id));if(m)m.read=true;save();render();toast('Aviso marcado como leído.');break;}case'delete-message':if(confirm('¿Eliminar este aviso de la demo?')){state.messages=state.messages.filter(x=>x.id!==Number(id));save();render();toast('Aviso eliminado.');}break;case'cancel-booking':{const b=state.bookings.find(x=>x.id===Number(id));if(!b)break;const c=classById(b.classId);if(c&&bookingCutoffPassed(c,b.date)){toast('No se puede cancelar dentro de los 40 minutos previos al inicio.',true);break;}if(confirm('¿Cancelar esta reserva?')){const wasConfirmed=b.status==='confirmado';b.status='Cancelado';const promoted=wasConfirmed?promoteWaitlist(b.classId,b.date):null;save();render();toast(promoted?'Reserva cancelada. Se confirmó automáticamente el turno de '+(memberById(promoted.memberId)?.name||'la siguiente persona')+'.':'Reserva cancelada y cupo liberado.');}break;}case'admin-cancel-booking':{const b=state.bookings.find(x=>x.id===Number(id));if(!b)break;const c=classById(b.classId);if(c&&bookingCutoffPassed(c,b.date)){toast('No se puede cancelar dentro de los 40 minutos previos al inicio.',true);break;}const wasConfirmed=b.status==='confirmado';b.status='Cancelado';const promoted=wasConfirmed?promoteWaitlist(b.classId,b.date):null;save();closeModal();render();toast(promoted?'Reserva quitada; se confirmó automáticamente el turno de '+(memberById(promoted.memberId)?.name||'la siguiente persona')+'.':'Reserva quitada; cupo liberado.');break;}case'prev-date':scheduleDate=shiftDate(scheduleDate,-1);render();break;case'next-date':scheduleDate=shiftDate(scheduleDate,1);render();break;case'close-modal':closeModal();break;}}
  function shiftDate(date,delta){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+delta);return d.toISOString().slice(0,10)}
  $('#navigation').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)navigate(b.dataset.view)});
  document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go);return}const act=e.target.closest('[data-action]');if(act){runAction(act.dataset.action,act.dataset.id);return}const tab=e.target.closest('[data-member-tab]');if(tab){memberTab=tab.dataset.memberTab;render();return}const rt=e.target.closest('[data-routine-filter]');if(rt){routineFilter=rt.dataset.routineFilter;render();return}});
  $('#roleSelect').addEventListener('change',e=>{setRole(e.target.value)});
  $('#mobileMenu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobileMenu').setAttribute('aria-expanded',String(open));});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false');}});
  document.addEventListener('click',e=>{if(window.matchMedia('(max-width: 760px)').matches&&$('#sidebar').classList.contains('open')&&!$('#sidebar').contains(e.target)&&!$('#mobileMenu').contains(e.target)){$('#sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false');}});
  $('#resetDemo').addEventListener('click',()=>{if(confirm('¿Vaciar el prototipo local? Se eliminarán los datos almacenados por esta demo en este navegador.')){state=seed();memberTab='all';memberSearch='';memberStatus='all';accountSearch='';scheduleDate=isoToday;routineFilter='Todas';localStorage.setItem(STORAGE_KEY,JSON.stringify(state));setRole('admin');toast('Prototipo local vacío.');}});
  $('#page').addEventListener('input',e=>{if(e.target.id==='memberSearch'){memberSearch=e.target.value;const pos=e.target.selectionStart;render();const input=$('#memberSearch');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='accountSearch'){accountSearch=e.target.value;const pos=e.target.selectionStart;render();const input=$('#accountSearch');input.focus();input.setSelectionRange(pos,pos)}});
  $('#page').addEventListener('change',e=>{if(e.target.id==='memberStatusFilter'){memberStatus=e.target.value;render()}if(e.target.id==='scheduleDate'){scheduleDate=e.target.value||isoToday;render()}});
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
  // Remove inherited click action dispatch on form buttons by closing native dialog safely.
  setRole(state.role||'admin');
})();
